--
-- Name: business_summary _RETURN; Type: RULE; Schema: public; Owner: postgres
--

CREATE OR REPLACE VIEW public.business_summary AS
 SELECT b.id,
    b.name,
    b.registration_number,
    b.city,
    b.industry,
    b.status,
    b.date_registered,
    count(DISTINCT l.id) AS license_count,
    count(DISTINCT i.id) AS inspection_count
   FROM ((public.businesses b
     LEFT JOIN public.licenses l ON ((l.business_id = b.id)))
     LEFT JOIN public.inspections i ON ((i.business_id = b.id)))
  GROUP BY b.id;


